SET lock_timeout='1s'; SET statement_timeout='5s';
CREATE TABLE identity.mfa_factors(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE RESTRICT,state text NOT NULL CHECK(state IN ('PENDING','ACTIVE','REPLACED','CANCELLED')),algorithm text NOT NULL CHECK(algorithm='TOTP_SHA1'),digits integer NOT NULL CHECK(digits=6),period_seconds integer NOT NULL CHECK(period_seconds=30),secret_ciphertext bytea NOT NULL,secret_nonce bytea NOT NULL CHECK(octet_length(secret_nonce)=12),key_version integer NOT NULL CHECK(key_version>0),failed_attempts integer NOT NULL DEFAULT 0 CHECK(failed_attempts BETWEEN 0 AND 5),denied_until timestamptz,last_accepted_counter bigint NOT NULL DEFAULT -1 CHECK(last_accepted_counter>=-1),created_at timestamptz NOT NULL,pending_expires_at timestamptz NOT NULL,activated_at timestamptz,replaced_at timestamptz,version bigint NOT NULL DEFAULT 1 CHECK(version>0),CHECK(pending_expires_at=created_at+interval '10 minutes'),CHECK(denied_until IS NULL OR (failed_attempts=5 AND denied_until>created_at)),CHECK((state='PENDING' AND activated_at IS NULL AND replaced_at IS NULL) OR (state='ACTIVE' AND activated_at IS NOT NULL AND replaced_at IS NULL) OR (state='REPLACED' AND activated_at IS NOT NULL AND replaced_at IS NOT NULL) OR (state='CANCELLED' AND activated_at IS NULL AND replaced_at IS NOT NULL)));
CREATE UNIQUE INDEX mfa_one_pending_user ON identity.mfa_factors(user_id) WHERE state='PENDING';
CREATE UNIQUE INDEX mfa_one_active_user ON identity.mfa_factors(user_id) WHERE state='ACTIVE';
CREATE TABLE identity.mfa_recovery_codes(id uuid PRIMARY KEY,factor_id uuid NOT NULL REFERENCES identity.mfa_factors(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE RESTRICT,code_hash bytea NOT NULL UNIQUE CHECK(octet_length(code_hash)=32),created_at timestamptz NOT NULL,consumed_at timestamptz,invalidated_at timestamptz,CHECK(consumed_at IS NULL OR consumed_at>=created_at),CHECK(invalidated_at IS NULL OR invalidated_at>=created_at),CHECK(NOT(consumed_at IS NOT NULL AND invalidated_at IS NOT NULL)));
CREATE INDEX mfa_recovery_available ON identity.mfa_recovery_codes(user_id,factor_id) WHERE consumed_at IS NULL AND invalidated_at IS NULL;
CREATE TABLE identity.mfa_transactions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE RESTRICT,purpose text NOT NULL CHECK(purpose='MFA_LOGIN'),token_hash bytea NOT NULL UNIQUE CHECK(octet_length(token_hash)=32),browser_binding_hash bytea NOT NULL CHECK(octet_length(browser_binding_hash)=32),primary_method text NOT NULL CHECK(primary_method IN ('PASSWORD','GOOGLE')),auth_epoch bigint NOT NULL CHECK(auth_epoch>0),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),denied_until timestamptz,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL,CHECK(expires_at=created_at+interval '5 minutes'),CHECK(denied_until IS NULL OR (attempts=5 AND denied_until>created_at)),CHECK(consumed_at IS NULL OR consumed_at>=created_at));
CREATE UNIQUE INDEX mfa_one_login_transaction_user ON identity.mfa_transactions(user_id) WHERE consumed_at IS NULL;
ALTER TABLE identity.sessions ADD COLUMN assurance_level text DEFAULT 'AAL1' CHECK(assurance_level IN ('AAL1','AAL2')),ADD COLUMN assured_at timestamptz,ADD COLUMN assurance_method text DEFAULT 'PRIMARY_ONLY' CHECK(assurance_method IN ('PRIMARY_ONLY','TOTP','RECOVERY_CODE'));
UPDATE identity.sessions SET assured_at=created_at WHERE assured_at IS NULL;
ALTER TABLE identity.sessions ALTER COLUMN assurance_level SET NOT NULL,ALTER COLUMN assured_at SET NOT NULL,ALTER COLUMN assurance_method SET NOT NULL,ADD CONSTRAINT session_assurance_shape CHECK((assurance_level='AAL1' AND assurance_method='PRIMARY_ONLY') OR (assurance_level='AAL2' AND assurance_method IN ('TOTP','RECOVERY_CODE'))),ADD CONSTRAINT session_assured_time CHECK(assured_at>=created_at AND assured_at<=last_seen_at);
ALTER TABLE identity.sessions ALTER COLUMN assurance_level DROP DEFAULT,ALTER COLUMN assurance_method DROP DEFAULT;
